"  useEffect(() => {
    setShowLoyaltyPopup(false);
  }, [customerPhone]);

  useEffect(() => {
    if (!customerPhone) {
      setSelectedCustomer(null);
      return;
    }
    const fullPhone = customerPhone.startsWith('+') ? customerPhone : customerCountryCode + customerPhone;
    const matched = customerDb[fullPhone];
    if (matched) {
      setSelectedCustomer(matched);
    } else {
      setSelectedCustomer(null);
    }
  }, [customerPhone, customerCountryCode, customerDb]);"
